import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as l,o as s,X as o,x as t,a as r,t as a}from"./chunks/vendor-vueuse.XPft87tp.js";const f=JSON.parse('{"title":"Vue 响应式原理","description":"","frontmatter":{},"headers":[],"relativePath":"vue/reactivity-principle.md","filePath":"vue/reactivity-principle.md","lastUpdated":1785917016000}'),d={name:"vue/reactivity-principle.md"};function p(n,e,u,c,v,g){return s(),l("div",null,[e[7]||(e[7]=o('<h1 id="vue-响应式原理" tabindex="-1">Vue 响应式原理 <a class="header-anchor" href="#vue-响应式原理" aria-label="Permalink to &quot;Vue 响应式原理&quot;">​</a></h1><h3 id="四个核心角色" tabindex="-1">四个核心角色 <a class="header-anchor" href="#四个核心角色" aria-label="Permalink to &quot;四个核心角色&quot;">​</a></h3><p>Vue 的响应式系统是<strong>数据劫持 + 发布订阅模式</strong>，由四个角色配合完成：Observer、Dep、Watcher、Compile。</p><p><strong>Observer（观察者）</strong>：把普通对象/数据通过 <code>Object.defineProperty</code>（Vue2）或 <code>Proxy</code>（Vue3）变成响应式数据。数据被读时触发 get，被写时触发 set。</p><p><strong>Dep（依赖管理器）</strong>：为每个响应式属性维护一个订阅者列表，列表中保存所有依赖该属性的 Watcher。数据变化时，Dep 会统一通知这些订阅者执行更新。</p><p><strong>Watcher（订阅者）</strong>：负责在数据变化后执行具体更新逻辑。每个组件的 render 函数通常会对应一个 Watcher，数据更新时 Dep 会通知相关 Watcher 重新执行。</p>',6)),t("p",null,[e[0]||(e[0]=t("strong",null,"Compile（编译器）",-1)),e[1]||(e[1]=r("：解析模板中的 ")),t("code",null,a(),1),e[2]||(e[2]=r("、")),e[3]||(e[3]=t("code",null,"v-model",-1)),e[4]||(e[4]=r(" 等指令，把它们替换成真实数据，同时为每个用到数据的地方创建 Watcher。"))]),e[8]||(e[8]=t("h3",{id:"一个完整的数据更新流程",tabindex:"-1"},[r("一个完整的数据更新流程 "),t("a",{class:"header-anchor",href:"#一个完整的数据更新流程","aria-label":'Permalink to "一个完整的数据更新流程"'},"​")],-1)),t("p",null,[e[5]||(e[5]=r("假设模板中使用了 ")),t("code",null,a(n.count),1),e[6]||(e[6]=r("，且 count 的初始值为 0："))]),e[9]||(e[9]=o('<ol><li><strong>初始化阶段</strong>：Compile 解析模板，识别到 <code>count</code> 被使用，并创建对应 Watcher</li><li><strong>依赖收集</strong>：Watcher 第一次执行时读取 <code>count</code>，触发 get 拦截 → Dep 将这个 Watcher 记录到订阅列表中</li><li><strong>数据变化</strong>：<code>count = 1</code>，触发 set 拦截 → Dep 通知订阅列表中的 Watcher</li><li><strong>视图更新</strong>：Watcher 收到通知后重新执行 render → 生成新虚拟 DOM → Diff → 更新真实 DOM</li></ol><h3 id="vue2-vs-vue3-的差异" tabindex="-1">Vue2 vs Vue3 的差异 <a class="header-anchor" href="#vue2-vs-vue3-的差异" aria-label="Permalink to &quot;Vue2 vs Vue3 的差异&quot;">​</a></h3><p>Vue2 使用 <code>Object.defineProperty</code> 逐个劫持属性，存在两个典型限制：新增/删除属性无法自动感知（因此需要 <code>$set</code> / <code>$delete</code>），数组下标修改也无法直接感知（需要重写 push/pop 等 7 个数组方法）。</p><p>Vue3 改用 <code>Proxy</code> 后，可以直接代理整个对象，新增属性、删除属性、数组下标修改都能被拦截。同时 Vue3 不需要在初始化阶段递归遍历所有属性，而是按需代理，初始化性能也更好。</p>',4))])}const h=i(d,[["render",p]]);export{f as __pageData,h as default};
